package hu.boltseged.auth;
import hu.boltseged.account.*; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {final AccountRepository repo;final PasswordEncoder enc;final byte[] secret;@Value("${app.jwt-expiration-minutes}")long mins;AuthController(AccountRepository r,PasswordEncoder e,@Value("${app.jwt-secret}")String s){repo=r;enc=e;secret=s.getBytes(StandardCharsets.UTF_8);}@PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody Login x){return repo.findByEmailIgnoreCase(x.email()).filter(a->a.isActive()&&enc.matches(x.password(),a.getPasswordHash())).<ResponseEntity<?>>map(a->{String t=Jwts.builder().subject(a.getEmail()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+mins*60000)).signWith(Keys.hmacShaKeyFor(secret)).compact();return ResponseEntity.ok(new Token(t,a.getRole()));}).orElse(ResponseEntity.status(401).body(Map.of("message","Invalid credentials")));}@PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody Register x){if(repo.findByEmailIgnoreCase(x.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already exists");Account a=repo.save(new Account(null,x.email(),enc.encode(x.password()),"CUSTOMER"));return ResponseEntity.status(HttpStatus.CREATED).body(new Registered(a.getId(),a.getEmail(),a.getRole()));}record Login(@Email @NotBlank String email,@NotBlank String password){}record Register(@Email @NotBlank String email,@NotBlank @Size(min=12)String password){}record Token(String token,String role){}record Registered(UUID id,String email,String role){} }
